const __quietstartKits = {
"ruleSuite": (// Project-authored generic task/step/repeat/schedule continuation.
// All application labels, routes, task IDs and geometry remain signed data.
// Normal progress waits retain their checkpoint; elapsed time alone never skips a task.
function createRuleSuiteKit(plan,dependencies={}){
const createSchedule=(// Author-side extraction of core/TaskSchedule.ets. No native calls, clocks or
// mutable module state: the original deadlines survive QuickJS tick rebuilds.
function createTaskSchedule(configuration) {
  const copy=value=>JSON.parse(JSON.stringify(value));
  const spec=copy(configuration),known=new Set(spec.groups.map(group=>group.id));
  if(!Array.isArray(spec.groups)||spec.groups.length>16||known.size!==spec.groups.length||
    !Array.isArray(spec.checkpoints)||!Array.isArray(spec.resumeTaskIds))throw Error('invalid-rule-suite-schedule-spec');
  for(const group of spec.groups){
    if(typeof group.id!=='string'||!group.id||typeof group.name!=='string'||
      !Array.isArray(group.taskIds)||!group.taskIds.includes(group.anchorTaskId)||
      !Number.isSafeInteger(group.intervalMs)||group.intervalMs<1000||group.intervalMs>86400000)throw Error('invalid-rule-suite-schedule-spec');
    if(group.availability)new RegExp(group.availability.countdownPattern);
  }
  function initial(owner=''){return{schema:1,owner,deadlines:[]};}
  function checkpoint(value){
    if(!value||value.schema!==1||typeof value.owner!=='string'||value.owner.length>160||
      !Array.isArray(value.deadlines)||value.deadlines.length>spec.groups.length||
      Object.keys(value).some(key=>!['schema','owner','deadlines'].includes(key)))throw Error('invalid-rule-suite-schedule-checkpoint');
    const ids=new Set();
    for(const deadline of value.deadlines){
      if(!deadline||!known.has(deadline.id)||ids.has(deadline.id)||typeof deadline.ready!=='boolean'||
        Object.keys(deadline).some(key=>!['id','at','ready','starts','consumedStarts','probeAt'].includes(key))||
        !['at','starts','probeAt'].every(key=>Number.isSafeInteger(deadline[key])&&deadline[key]>=0)||
        !Number.isSafeInteger(deadline.consumedStarts)||deadline.consumedStarts< -1||deadline.consumedStarts>deadline.starts)throw Error('invalid-rule-suite-schedule-checkpoint');
      ids.add(deadline.id);
    }
    return copy(value);
