      deadline.consumedStarts=deadline.starts;deadline.ready=false;deadline.at=now+group.intervalMs;deadline.probeAt=deadline.at;
      for(const id of group.taskIds)if(!taskIds.includes(id))taskIds.push(id);
    }
    if(taskIds.length)for(const id of spec.resumeTaskIds)if(!taskIds.includes(id))taskIds.push(id);
    return{checkpoint:cp,taskIds};
  }
  function due(value,taskId,beforeStep,now){return isCheckpoint(taskId,beforeStep)?takeDue(value,now,false):{checkpoint:checkpoint(value),taskIds:[]};}
  function nextWakeAt(value,now){const cp=checkpoint(value);timestamp(now);let next=0;
    for(const deadline of cp.deadlines){const at=deadline.ready&&deadline.consumedStarts!==deadline.starts?now:deadline.at>0?deadline.at:deadline.probeAt;
      if(at>0&&(next===0||at<next))next=at;}return next;
  }
  function countdowns(value,now){const cp=checkpoint(value);timestamp(now);return spec.groups.map(group=>{
    const deadline=cp.deadlines.find(item=>item.id===group.id),at=deadline?.at??0;
    if(deadline?.ready)return group.name+' 可继续';if(!at)return'';
    const seconds=Math.max(0,Math.ceil((at-now)/1000));return group.name+' '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');
  }).filter(Boolean);}
  return{initial,configure,reset:()=>initial(),started,isCheckpoint,observe,observeFrame,due,
    dueIdle:(cp,now)=>takeDue(cp,now,true),nextWakeAt,countdowns,checkpoint};
}
);
const createFlow=(// The original task declarations remain data. This author-side continuation
// owns their step/repeat/checkpoint state; native ports only supply owned nodes
// and fresh opaque input references. No native workflow worker is called.
function createTaskFlow(plan, dependencies) {
  const copy=value=>JSON.parse(JSON.stringify(value)),compact=value=>String(value||'').replace(/[\s\u200b\ufeff]/g,'');
  const allTasks=plan.originalRules.tasks.slice().sort((a,b)=>a.priority-b.priority),byId=new Map(allTasks.map(t=>[t.id,t]));
  const tasks=allTasks.filter(task=>!(plan.flowPolicy?.replacedTaskIds||[]).includes(task.id));
  const schedule=dependencies.createSchedule(plan.scheduling||{groups:[],checkpoints:[],resumeTaskIds:[]});
  const owner=plan.originalRules.appliesTo[0];
