        if (!node || depth > 128 || ++inspected > 20000 || node.attributes?.visible === 'false') {
            return false;
        }
        const children = node.children ?? [];
        const visible = children.filter((child) => child.attributes?.visible !== 'false');
        const titles = visible.filter((child) => label(child) === title);
        if (titles.length === 1) {
            const heading = snapshotBounds(titles[0].attributes?.bounds ?? '');
            if (heading) {
                const states = visible.filter((child) => {
                    const box = snapshotBounds(child.attributes?.bounds ?? '');
                    return label(child) === state && !!box && sameRow(heading, box);
                });
                const active = visible.some((child) => {
                    const box = snapshotBounds(child.attributes?.bounds ?? '');
                    return activeLabels.includes(label(child)) && !!box && sameRow(heading, box);
                });
                if (states.length === 1 && !active) {
                    const terminal = snapshotBounds(states[0].attributes?.bounds ?? '');
                    const left = Math.min(heading.right, terminal.right), right = Math.max(heading.left, terminal.left);
                    const intervening = visible.some((child) => {
                        if (child === titles[0] || child === states[0] || !label(child)) {
                            return false;
                        }
                        const box = snapshotBounds(child.attributes?.bounds ?? '');
                        return !!box && box.left >= left && box.right <= right && sameRow(heading, box);
                    });
