    if(!window)return[];const need=step.need||{},limit={...(task.defaults?.limit||{}),...(find.limit||{})};
    if(!ignoreNeed&&((need.visibleText?.length&&!need.visibleText.some(word=>has(values,word)))||need.absentText?.some(word=>has(values,word))||
      need.evidence?.text?.length&&!need.evidence.text.some(word=>has(values,word))||need.absentOnScreenText?.some(word=>hasOnScreen(values,word,window))))return[];
