      const direct=(find.match||[]).some(word=>label.includes(compact(word)));
      const idHit=(find.idHints||[]).some(hint=>{const words=Array.isArray(hint)?hint.slice(0,-1):hint.words||[];return words.length&&words.every(word=>compact(a.id).toLowerCase().includes(compact(word).toLowerCase()));});
