        (limit.maxWidth!==undefined&&(b.right-b.left)/w>limit.maxWidth)||(limit.maxHeight!==undefined&&(b.bottom-b.top)/h>limit.maxHeight)||
        (limit.maxArea!==undefined&&(b.right-b.left)*(b.bottom-b.top)/(w*h)>limit.maxArea))continue;
      if(find.sameParentText?.length&&!(value.parent?.children||[]).some(s=>s!==value.node&&s.attributes?.visible!=='false'&&find.sameParentText.some(t=>compact(s.attributes?.text||s.attributes?.description)===compact(t))))continue;
      if(find.sameParentType?.length&&!(value.parent?.children||[]).some(s=>s!==value.node&&s.attributes?.visible!=='false'&&find.sameParentType.includes(s.attributes?.type)))continue;
      if(step.do?.capability!=='observe'&&!a.targetRef)continue;
