          return output({checkpoint:before,nextAt:before.nextAt,status:'waiting',message:'目标已变化，重新确认'},await ctx.clock.now());}
        if(['applied','already-applied'].includes(receipt.status)&&action.kind==='tap'){
          const latest=await ctx.rules.resolve(actionBinding.visitQuery);if(latest.matched)receipt.visitTicket=latest.visitTicket;}
        decision=suite.commit(decision,receipt);
        decision.checkpoint.deferrals=0;
        if(receipt.consumed)decision.checkpoint.visit.actionSequence=Math.max(decision.checkpoint.visit.actionSequence,receipt.sequence+1);
      }
    }
    if(decision.status==='paused')throw Error(decision.message||'qq-input-unconfirmed');
    if(decision.status==='complete'){
      if (decision.outcome === 'visited') before.completedVisits = (before.completedVisits || 0) + 1;
      if (goal > 0 && (before.completedVisits || 0) >= goal) observation.nativeFacts.allowNewVisits = false;
      const repeat=suite.repeatAfterReward(decision.checkpoint,observation.nativeFacts,await ctx.clock.now());
      if(repeat)decision={...decision,status:'running',checkpoint:repeat};
    }
    step=flow.landed(before,decision,await ctx.clock.now());
    if (finishing && decision.status === 'complete') {
      flow.restrict(selection); step=flow.cancelDisabled(step.checkpoint,await ctx.clock.now());
    }
    now=await ctx.clock.now();
    if(!inputIssued&&decision.status==='complete'&&!(goal>0&&(step.checkpoint.completedVisits||0)>=goal)&&observation.flowFrame?.complete===true&&step.status!=='complete'&&step.nextAt<=now){
      before=step.checkpoint;continue;
    }
  }else{
    const frame=(await readObservation()).queries?.owner;
    if(!frame)throw Error('coherent-owner-query-missing');step=await recoverInstallCondition(ctx,before,frame,now)||flow.decideReady(before,frame,now);
    if(step.command?.kind==='landing'){
      step.checkpoint.landing=step.checkpoint.landingDormant||suite.initial(step.command.taskId,now,step.checkpoint.actionSequence);
      step.checkpoint.landingDormant=null;step.checkpoint.nextAt=now;
      before=step.checkpoint;continue;
    }else if(['tap','swipe'].includes(step.command?.kind)){
      const action={kind:step.command.kind,idempotencyKey:ctx.run.id+'/'+step.command.sequence};
      if(action.kind==='tap')action.targetRef=step.command.targetRef;else action.ruleRef=step.command.ruleRef;
      const receipt=await ctx.actions.perform(action);
      step=flow.commit(step.checkpoint,step.command,receipt,await ctx.clock.now());
      if(action.kind==='swipe'&&step.checkpoint.landingDormant&&['applied','already-applied'].includes(receipt.status))
        step.checkpoint.landingDormant=suite.retryAfterSearch(step.checkpoint.landingDormant,receipt.at);
    }
  }
  break;
  }
  const result=output(step,await ctx.clock.now());await ctx.ui.publish({kind:'capsule',message:result.message,stopped:result.status==='complete'});return result;
}

function installCondition(frame){
  const values=flow.nodes(frame),titles=values.filter(value=>value.label==='下载并安装后需打开app浏览15秒才可获得奖励');
  if(!titles.length)return{present:false};
  const pending={present:true};
  if(frame.ownerValid!==true||frame.complete!==true||titles.length!==1||!values.some(value=>value.label==='金币TAB'))return pending;
  const card=titles[0].parent,ctas=values.filter(value=>value.a.type==='link'&&value.a.clickable==='true'&&value.label==='去浏览'&&value.parents.includes(card)),
    closes=values.filter(value=>value.a.type==='link'&&value.a.clickable==='true'&&value.label==='关闭'&&value.parents.includes(card));
  return card&&ctas.length===1&&closes.length===1?{present:true,bounds:closes[0].box}:pending;
}

async function recoverInstallCondition(ctx,before,frame,now){
  if(before.taskId!=='quietstart.qqmusic-coin-center-gift-cycle')return null;
  const condition=installCondition(frame),waiting=note=>({checkpoint:before,nextAt:now+350,status:'waiting',message:note});
  if(before.installConditionRecovery){
    if(condition.present||frame.ownerValid!==true||frame.complete!==true)return waiting('等待安装提示关闭结果，不重复点击');
    const values=flow.nodes(frame),expected=__quietstartQqPlan.visits.find(visit=>visit.taskId===before.taskId).spec.unavailableRecovery.expectedAnyText;
    if(!expected.some(word=>values.some(value=>value.label.includes(compact(word)))))return waiting('等待原金币任务页确认');
    delete before.installConditionRecovery;
    const recovered=suite.initial(before.taskId,now,before.actionSequence);
    Object.assign(recovered.visit,{done:true,outcome:'unavailable',note:'礼物任务仍待完成：安装条件未满足；已关闭提示，继续其他任务'});
    return flow.landed(before,{checkpoint:recovered,status:'complete',outcome:'unavailable',message:recovered.visit.note},now);
  }
  if(!condition.present)return null;
  if(!condition.bounds)return waiting('等待确认安装提示关闭入口');
  const target=await ctx.rules.resolve('giftInstallConditionClose');
  if(!target.matched||!target.targetRef||!target.bounds||!['left','top','right','bottom'].every(key=>target.bounds[key]===condition.bounds[key]))
    return waiting('等待确认安装提示关闭入口');
  const receipt=await ctx.actions.perform({kind:'tap',targetRef:target.targetRef,idempotencyKey:ctx.run.id+'/'+before.actionSequence});
  if(receipt.sequence!==before.actionSequence)throw Error('qq-install-condition-receipt-sequence');
  if(receipt.status==='not-dispatched'&&!receipt.consumed)return waiting('安装提示已变化，重新确认关闭入口');
  if(!['applied','already-applied'].includes(receipt.status))throw Error('qq-install-condition-close-unconfirmed');
  before.actionSequence=receipt.sequence+1;
  before.pendingTasks??={};before.pendingTasks[before.taskId]={state:'pending',reason:'requires-install',step:before.step,cycles:before.cycles,
    landingDone:before.landingDone,actionSequence:before.actionSequence,closedAt:receipt.at};
  before.installConditionRecovery={taskId:before.taskId,at:receipt.at};
  return waiting('礼物任务待完成，确认安装提示已关闭');
}

async function settleOptionalReward(ctx,before,now) {
  const frame=await ctx.rules.resolve('owner');
  if (!frame.ownerValid || frame.complete !== true) return {checkpoint:before,nextAt:now+350,status:'waiting',message:'等待领奖页可读，保留当前任务'};
  const labels=flow.nodes(frame).map(node=>node.label);
  if (!labels.some(label=>/^(?:恭喜(?:你)?(?:已)?获得|已获得[0-9])/.test(label)) || !labels.some(label=>['观看广告','观看下一条'].includes(label))) return null;
  const close=await ctx.rules.resolve('optionalRewardClose');
  if (!close.matched || !close.targetRef) return {checkpoint:before,nextAt:now+350,status:'waiting',message:'追加广告已关闭，等待确认领奖弹窗的关闭入口'};
  const receipt=await ctx.actions.perform({kind:'tap',targetRef:close.targetRef,idempotencyKey:ctx.run.id+'/'+before.actionSequence});
  if (['applied','already-applied'].includes(receipt.status)) before.actionSequence=receipt.sequence+1;
  else if (receipt.status !== 'not-dispatched' || receipt.consumed) throw Error('qq-optional-reward-close-unconfirmed');
  return {checkpoint:before,nextAt:now+350,status:'waiting',message:'已关闭追加奖励弹窗，等待原任务页确认'};
}

const __quietstartConfiguredControls={"tasks":[{"id":"quietstart.qqmusic-free-listen-video-cycle","key":"task.quietstart.qqmusic-free-listen-video-cycle"}],"stages":[],"safeFinish":true,"supportTasks":[]};
// Author-side settings adapter. This never changes target declarations, input
// permissions, original checkpoints, or an application's completion conditions.
export async function onEvent(ctx, event) {
  const config = await ctx.config.read();
  const controls = typeof __quietstartConfiguredControls === 'object' ? __quietstartConfiguredControls : {};
  if (controls.tasks?.length) {
    const disabled = new Set(controls.tasks.filter(task => config[task.key] === false).map(task => task.id));
    // Local settings only subtract from the host's current authorized list.
    // Missing native lists retain the original adapter's fail-closed behavior.
    if (Array.isArray(event?.enabledTaskIds)) {
      const selected = event.enabledTaskIds.filter(id => !disabled.has(id));
      if (controls.supportTasks?.length && controls.tasks.filter(task => !controls.supportTasks.includes(task.id)).every(task => disabled.has(task.id))) selected.splice(0);
      event = controls.safeFinish ? { ...event, selectedTaskIds: selected } : { ...event, enabledTaskIds: selected };
    }
    else if (disabled.size === controls.tasks.length) event = { ...event, enabledTaskIds: [] };
  }
  const prefix = typeof config.progressPrefix === 'string' ? config.progressPrefix.trim() : '';
  const message = text => prefix && typeof text === 'string' && text ? (prefix + ' · ' + text).slice(0, 500) : text;
  const port = { ...ctx, config: { ...ctx.config, read: async () => config },
    ...(prefix && ctx.ui?.publish ? { ui: { ...ctx.ui,
